    let stored = a.db.list_swarm_personas(&sid).unwrap();
    assert_eq!(stored.len(), 1);
    assert_eq!(stored[0].blurb, "pokes holes in every claim");

    assert!(!a.session.as_ref().unwrap().swarm_mode);
