            let mut s = self
                .db
                .create_session(&title, &model, &self.active_space.id)?;
            // Carry a pre-session `/web` toggle onto the session it creates.
            if self.web_mode {
                s.web_mode = true;
                let _ = self.db.set_session_web_mode(&s.id, true);
